/* Socket.IO is a third-party library.
   In production, use the actual Socket.IO client from CDN.
   This is just a minimal placeholder for development. */
console.log("Socket.IO would be loaded from CDN in production");

// Minimal Socket.IO functionality for testing
if (typeof window.io === 'undefined') {
    window.io = function(url, options) {
        console.log("Socket.IO connecting to:", url, options);
        
        const socket = {
            connected: false,
            disconnected: true,
            id: null,
            
            // Event handlers
            _handlers: {},
            
            // Connect
            connect: function() {
                console.log("Socket.IO connect");
                this.connected = true;
                this.disconnected = false;
                this.id = 'test_socket_id_' + Math.random().toString(36).substr(2, 9);
                
                // Trigger connect event
                setTimeout(() => {
                    if (this._handlers['connect']) {
                        this._handlers['connect'].forEach(handler => handler());
                    }
                }, 100);
                
                return this;
            },
            
            // Disconnect
            disconnect: function() {
                console.log("Socket.IO disconnect");
                this.connected = false;
                this.disconnected = true;
                
                // Trigger disconnect event
                setTimeout(() => {
                    if (this._handlers['disconnect']) {
                        this._handlers['disconnect'].forEach(handler => handler());
                    }
                }, 100);
                
                return this;
            },
            
            // Emit event
            emit: function(event, data, callback) {
                console.log("Socket.IO emit:", event, data);
                
                // Simulate server response for certain events
                if (event === 'authenticate') {
                    setTimeout(() => {
                        if (data && data.token) {
                            // Simulate successful authentication
                            this.onEvent('authenticated', {
                                success: true,
                                message: 'Authenticated successfully'
                            });
                        } else {
                            this.onEvent('error', {
                                success: false,
                                error: 'Authentication failed'
                            });
                        }
                        
                        if (callback) callback({ success: true });
                    }, 50);
                } else if (event === 'subscribe_video') {
                    setTimeout(() => {
                        this.onEvent('subscribed', {
                            success: true,
                            video_id: data ? data.video_id : null
                        });
                        
                        if (callback) callback({ success: true });
                    }, 50);
                } else if (event === 'unsubscribe_video') {
                    setTimeout(() => {
                        this.onEvent('unsubscribed', {
                            success: true,
                            video_id: data ? data.video_id : null
                        });
                        
                        if (callback) callback({ success: true });
                    }, 50);
                } else {
                    if (callback) callback({ success: true });
                }
                
                return this;
            },
            
            // Listen for event
            on: function(event, handler) {
                console.log("Socket.IO on:", event);
                if (!this._handlers[event]) {
                    this._handlers[event] = [];
                }
                this._handlers[event].push(handler);
                return this;
            },
            
            // Remove event listener
            off: function(event, handler) {
                console.log("Socket.IO off:", event);
                if (this._handlers[event]) {
                    if (handler) {
                        const index = this._handlers[event].indexOf(handler);
                        if (index > -1) {
                            this._handlers[event].splice(index, 1);
                        }
                    } else {
                        delete this._handlers[event];
                    }
                }
                return this;
            },
            
            // Trigger event (for testing)
            onEvent: function(event, data) {
                console.log("Socket.IO trigger event:", event, data);
                if (this._handlers[event]) {
                    this._handlers[event].forEach(handler => handler(data));
                }
            },
            
            // Close connection
            close: function() {
                return this.disconnect();
            }
        };
        
        // Auto-connect after a delay
        setTimeout(() => socket.connect(), 200);
        
        return socket;
    };
}